function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue == oldValue) {
        return;
    }

    var validOutcomes = [
        'Amend and CONF',
        'Confirm Trade',
        'Settle Trade'
    ];

    if (validOutcomes.indexOf(newValue) !== -1) {
        var bulkSysId = g_form.getUniqueValue();
        var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkTradeUtils');
        ga.addParam('sysparm_name', 'getBandSummary');
        ga.addParam('sysparm_bulkid', bulkSysId);
        ga.getXMLAnswer(function(response) {
            var summary = JSON.parse(response);
            var total = summary.total;
            var bandCounts = summary.bandCounts;
            var message = '<b>You are submitting ' + total + ' tasks.<b><br/>';
            for (var band in bandCounts) {
                if (band === '' || band === 'Unknown') {
                    message += '<b> for ' + bandCounts[band] + ' tasks: checker required<b><br/>';
                } else {
                    message += '<b> for ' + bandCounts[band] + ' tasks: ' + band + ' checker required<b><br/>';
                }
            }
            g_form.addInfoMessage(message);
        });
    }
}
